import { toggleNotifications } from "./actions"
import {
  getCurrentUserId,
  getNotificationPreference,
} from "@/lib/notifications"

export default async function Home() {
  const userId = getCurrentUserId()
  const enabled = await getNotificationPreference(userId)

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently <strong>{enabled ? "ON" : "OFF"}</strong>.
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          {enabled ? "Turn notifications OFF" : "Turn notifications ON"}
        </button>
      </form>
    </main>
  )
}

